Base.:+(m1::MatsubaraIndex{Bose}, m2::MatsubaraIndex{Bose})::MatsubaraIndex{Bose}   = MatsubaraIndex(Integer(m1) + Integer(m2),Bose)
Base.:+(m1::MatsubaraIndex{Bose}, n2::MatsubaraIndex{Fermi})::MatsubaraIndex{Fermi} = MatsubaraIndex(Integer(m1) + Integer(n2),Fermi)
Base.:+(n1::MatsubaraIndex{Fermi}, m2::MatsubaraIndex{Bose})::MatsubaraIndex{Fermi} = MatsubaraIndex(Integer(n1) + Integer(m2),Fermi)
Base.:+(n1::MatsubaraIndex{Fermi}, n2::MatsubaraIndex{Fermi})::MatsubaraIndex{Bose} = MatsubaraIndex(Integer(n1) + Integer(n2) + 1, Bose)
Base.:-(m1::MatsubaraIndex{Bose}, m2::MatsubaraIndex{Bose})::MatsubaraIndex{Bose}   = MatsubaraIndex(Integer(m1) - Integer(m2),Bose)
Base.:-(m1::MatsubaraIndex{Bose}, n2::MatsubaraIndex{Fermi})::MatsubaraIndex{Fermi} = MatsubaraIndex(Integer(m1) - Integer(n2) - 1, Fermi)
Base.:-(n1::MatsubaraIndex{Fermi}, m2::MatsubaraIndex{Bose})::MatsubaraIndex{Fermi} = MatsubaraIndex(Integer(n1) - Integer(m2), Fermi)
Base.:-(n1::MatsubaraIndex{Fermi}, n2::MatsubaraIndex{Fermi})::MatsubaraIndex{Bose} = MatsubaraIndex(Integer(n1) - Integer(n2), Bose)
Base.:-(m1::MatsubaraIndex{Bose})::MatsubaraIndex{Bose}   = MatsubaraIndex(-Integer(m1),Bose)
Base.:-(n1::MatsubaraIndex{Fermi})::MatsubaraIndex{Fermi} = MatsubaraIndex(-Integer(n1) + 1, Fermi)